class WavTokenizerConv1d(nn.Module):
    """Conv1d with asymmetric or causal padding and normalization."""

    def __init__(
        self, config, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, dilation: int = 1
    ):
        super().__init__()
        self.causal = config.use_causal_conv
        self.pad_mode = config.pad_mode
        self.norm_type = config.norm_type

        if self.norm_type not in ["weight_norm", "time_group_norm"]:
            raise ValueError(
                f'self.norm_type must be one of `"weight_norm"`, `"time_group_norm"`), got {self.norm_type}'
            )

        # warn user on unusual setup between dilation and stride
        if stride > 1 and dilation > 1:
            logger.warning(
                "WavTokenizerConv1d has been initialized with stride > 1 and dilation > 1"
                f" (kernel_size={kernel_size} stride={stride}, dilation={dilation})."
            )

        self.conv = nn.Conv1d(in_channels, out_channels, kernel_size, stride, dilation=dilation)
        weight_norm = nn.utils.weight_norm
        if hasattr(nn.utils.parametrizations, "weight_norm"):
            weight_norm = nn.utils.parametrizations.weight_norm

        if self.norm_type == "weight_norm":
            self.conv = weight_norm(self.conv)
        elif self.norm_type == "time_group_norm":
            self.norm = nn.GroupNorm(1, out_channels)

        kernel_size = self.conv.kernel_size[0]
        stride = torch.tensor(self.conv.stride[0], dtype=torch.int64)
        dilation = self.conv.dilation[0]

        # Effective kernel size with dilations.
        kernel_size = torch.tensor((kernel_size - 1) * dilation + 1, dtype=torch.int64)

        self.register_buffer("stride", stride, persistent=False)
        self.register_buffer("kernel_size", kernel_size, persistent=False)
        self.register_buffer("padding_total", kernel_size - stride, persistent=False)

    def _get_extra_padding_for_conv1d(
        self,
        hidden_states: torch.Tensor,
    ) -> torch.Tensor:
        """See `pad_for_conv1d`."""
        length = hidden_states.shape[-1]
        n_frames = (length - self.kernel_size + self.padding_total) / self.stride + 1
        n_frames = torch.ceil(n_frames).to(torch.int64) - 1
        ideal_length = n_frames * self.stride + self.kernel_size - self.padding_total

        return ideal_length - length

    @staticmethod
    def _pad1d(hidden_states: torch.Tensor, paddings: tuple[int, int], mode: str = "zero", value: float = 0.0):
        """Tiny wrapper around torch.nn.functional.pad, just to allow for reflect padding on small input.
        If this is the case, we insert extra 0 padding to the right before the reflection happens.
        """
        length = hidden_states.shape[-1]
        padding_left, padding_right = paddings
        if mode != "reflect":
            return nn.functional.pad(hidden_states, paddings, mode, value)

        max_pad = max(padding_left, padding_right)
        extra_pad = 0
        if length <= max_pad:
            extra_pad = max_pad - length + 1
            hidden_states = nn.functional.pad(hidden_states, (0, extra_pad))
        padded = nn.functional.pad(hidden_states, paddings, mode, value)
        end = padded.shape[-1] - extra_pad
        return padded[..., :end]

    def forward(self, hidden_states):
        extra_padding = self._get_extra_padding_for_conv1d(hidden_states)

        if self.causal:
            # Left padding for causal
            hidden_states = self._pad1d(hidden_states, (self.padding_total, extra_padding), mode=self.pad_mode)
        else:
            # Asymmetric padding required for odd strides
            padding_right = self.padding_total // 2
            padding_left = self.padding_total - padding_right
            hidden_states = self._pad1d(
                hidden_states, (padding_left, padding_right + extra_padding), mode=self.pad_mode
            )

        hidden_states = self.conv(hidden_states)

        if self.norm_type == "time_group_norm":
            hidden_states = self.norm(hidden_states)

        return hidden_states


class WavTokenizerLSTM(nn.Module):
    """
    LSTM without worrying about the hidden state, nor the layout of the data. Expects input as convolutional layout.
    """

    def __init__(self, config: WavTokenizerConfig, dimension: int):
        super().__init__()
        self.lstm = nn.LSTM(dimension, dimension, config.num_lstm_layers)

    def forward(self, hidden_states):
        hidden_states = hidden_states.permute(2, 0, 1)
        hidden_states = self.lstm(hidden_states)[0] + hidden_states
        hidden_states = hidden_states.permute(1, 2, 0)
        return hidden_states


class WavTokenizerResnetBlock(nn.Module):
    """
    Residual block from SEANet model as used by WavTokenizer.
    """

    def __init__(self, config: WavTokenizerConfig, dim: int, dilations: list[int]):
        super().__init__()
        kernel_sizes = (config.residual_kernel_size, 1)
        if len(kernel_sizes) != len(dilations):
            raise ValueError("Number of kernel sizes should match number of dilations")

        hidden = dim // config.compress
        block = []
        for i, (kernel_size, dilation) in enumerate(zip(kernel_sizes, dilations)):
            in_chs = dim if i == 0 else hidden
            out_chs = dim if i == len(kernel_sizes) - 1 else hidden
            block += [nn.ELU()]
            block += [WavTokenizerConv1d(config, in_chs, out_chs, kernel_size, dilation=dilation)]
        self.block = nn.ModuleList(block)

        if config.use_conv_shortcut:
            self.shortcut = WavTokenizerConv1d(config, dim, dim, kernel_size=1)
        else:
            self.shortcut = nn.Identity()

    def forward(self, hidden_states):
        residual = hidden_states
        for layer in self.block:
            hidden_states = layer(hidden_states)

        return self.shortcut(residual) + hidden_states


class WavTokenizerEncoder(nn.Module):
    """SEANet encoder as used by WavTokenizer."""

    def __init__(self, config: WavTokenizerConfig):
        super().__init__()
        model = [WavTokenizerConv1d(config, config.audio_channels, config.num_filters, config.kernel_size)]
        scaling = 1

        # Downsample to raw audio scale
        for ratio in reversed(config.upsampling_ratios):
            current_scale = scaling * config.num_filters
            # Add residual layers
            for j in range(config.num_residual_layers):
                model += [WavTokenizerResnetBlock(config, current_scale, [config.dilation_growth_rate**j, 1])]
            # Add downsampling layers
            model += [nn.ELU()]
            model += [
                WavTokenizerConv1d(config, current_scale, current_scale * 2, kernel_size=ratio * 2, stride=ratio)
            ]
            scaling *= 2

        model += [WavTokenizerLSTM(config, scaling * config.num_filters)]
        model += [nn.ELU()]
        model += [
            WavTokenizerConv1d(config, scaling * config.num_filters, config.hidden_size, config.last_kernel_size)
        ]

        self.layers = nn.ModuleList(model)

    def forward(self, hidden_states):
        for layer in self.layers:
            hidden_states = layer(hidden_states)
        return hidden_states


class WavTokenizerEuclideanCodebook(nn.Module):
    """Codebook with Euclidean distance."""

    def __init__(self, config: WavTokenizerConfig):
        super().__init__()
        embed = torch.zeros(config.codebook_size, config.codebook_dim)

        self.codebook_size = config.codebook_size

        self.register_buffer("inited", torch.Tensor([True]))
        self.register_buffer("cluster_size", torch.zeros(config.codebook_size))
        self.register_buffer("embed", embed)
        self.register_buffer("embed_avg", embed.clone())

    def quantize(self, hidden_states):
        embed = self.embed.t()
        scaled_states = hidden_states.pow(2).sum(1, keepdim=True)
        dist = -(scaled_states - 2 * hidden_states @ embed + embed.pow(2).sum(0, keepdim=True))
        embed_ind = dist.max(dim=-1).indices
        return embed_ind

    def encode(self, hidden_states):
        shape = hidden_states.shape
        # pre-process
        hidden_states = hidden_states.reshape((-1, shape[-1]))
        # quantize
        embed_ind = self.quantize(hidden_states)
        # post-process
        embed_ind = embed_ind.view(*shape[:-1])
        return embed_ind

    def decode(self, embed_ind):
        quantize = nn.functional.embedding(embed_ind, self.embed)
        return quantize


class WavTokenizerVectorQuantization(nn.Module):
    """
    Vector quantization implementation. Currently supports only euclidean distance.
    """

    def __init__(self, config: WavTokenizerConfig):
        super().__init__()
        self.codebook = WavTokenizerEuclideanCodebook(config)

    def encode(self, hidden_states):
        hidden_states = hidden_states.permute(0, 2, 1)
        embed_in = self.codebook.encode(hidden_states)
        return embed_in

    def decode(self, embed_ind):
        quantize = self.codebook.decode(embed_ind)
        quantize = quantize.permute(0, 2, 1)
        return quantize


class WavTokenizerAdaLayerNorm(nn.Module):
    """
    Adaptive layer norm whose scale and shift are looked up from condition embeddings (Vocos `AdaLayerNorm`).
    WavTokenizer conditions on a bandwidth id at training time; at inference the id is always 0.
    """

    def __init__(self, config: WavTokenizerConfig):
        super().__init__()
        self.dim = config.decoder_hidden_size
        self.eps = config.norm_eps
        self.scale = nn.Embedding(config.adanorm_num_embeddings, config.decoder_hidden_size)
        self.shift = nn.Embedding(config.adanorm_num_embeddings, config.decoder_hidden_size)

    def forward(self, hidden_states: torch.Tensor, cond_embedding_id: torch.Tensor) -> torch.Tensor:
        scale = self.scale(cond_embedding_id)
        shift = self.shift(cond_embedding_id)
        hidden_states = F.layer_norm(hidden_states, (self.dim,), eps=self.eps)
        return hidden_states * scale + shift


class WavTokenizerConvNeXtBlock(nn.Module):
    """ConvNeXt block adapted for 1D audio signals (Vocos `ConvNeXtBlock` with adaptive layer norm)."""

    def __init__(self, config: WavTokenizerConfig):
        super().__init__()
        dim = config.decoder_hidden_size
        self.dwconv = nn.Conv1d(dim, dim, kernel_size=7, padding=3, groups=dim)
        self.norm = WavTokenizerAdaLayerNorm(config)
        self.pwconv1 = nn.Linear(dim, config.decoder_intermediate_size)
        self.act = nn.GELU()
        self.pwconv2 = nn.Linear(config.decoder_intermediate_size, dim)
        self.gamma = nn.Parameter(torch.full((dim,), 1.0 / config.decoder_num_layers))

    def forward(self, hidden_states: torch.Tensor, cond_embedding_id: torch.Tensor) -> torch.Tensor:
        residual = hidden_states
        hidden_states = self.dwconv(hidden_states)
        hidden_states = hidden_states.transpose(1, 2)
        hidden_states = self.norm(hidden_states, cond_embedding_id)
        hidden_states = self.pwconv1(hidden_states)
        hidden_states = self.act(hidden_states)
        hidden_states = self.pwconv2(hidden_states)
        hidden_states = self.gamma * hidden_states
        hidden_states = hidden_states.transpose(1, 2)
        return residual + hidden_states


class WavTokenizerVocosResnetBlock(nn.Module):
    """Residual block of the decoder positional net (GroupNorm + SiLU + Conv1d, twice)."""

    def __init__(self, config: WavTokenizerConfig):
        super().__init__()
        dim = config.decoder_hidden_size
        self.norm1 = nn.GroupNorm(config.decoder_attention_num_groups, dim, eps=config.norm_eps)
        self.conv1 = nn.Conv1d(dim, dim, kernel_size=3, stride=1, padding=1)
        self.norm2 = nn.GroupNorm(config.decoder_attention_num_groups, dim, eps=config.norm_eps)
        self.dropout = nn.Dropout(0.1)
        self.conv2 = nn.Conv1d(dim, dim, kernel_size=3, stride=1, padding=1)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        residual = hidden_states
        hidden_states = self.norm1(hidden_states)
        hidden_states = hidden_states * torch.sigmoid(hidden_states)
        hidden_states = self.conv1(hidden_states)
        hidden_states = self.norm2(hidden_states)
        hidden_states = hidden_states * torch.sigmoid(hidden_states)
        hidden_states = self.dropout(hidden_states)
        hidden_states = self.conv2(hidden_states)
        return residual + hidden_states


class WavTokenizerVocosAttention(nn.Module):
    """Single-head self-attention over time with 1x1 convolutions (decoder positional net)."""

    def __init__(self, config: WavTokenizerConfig):
        super().__init__()
        dim = config.decoder_hidden_size
        self.norm = nn.GroupNorm(config.decoder_attention_num_groups, dim, eps=config.norm_eps)
        self.q = nn.Conv1d(dim, dim, kernel_size=1)
        self.k = nn.Conv1d(dim, dim, kernel_size=1)
        self.v = nn.Conv1d(dim, dim, kernel_size=1)
        self.proj_out = nn.Conv1d(dim, dim, kernel_size=1)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        residual = hidden_states
        hidden_states = self.norm(hidden_states)
        query = self.q(hidden_states)
        key = self.k(hidden_states)
        value = self.v(hidden_states)

        batch_size, channels, seq_len = query.shape
        attn_weights = torch.bmm(query.permute(0, 2, 1), key) * channels**-0.5
        attn_weights = F.softmax(attn_weights, dim=2)
        hidden_states = torch.bmm(value, attn_weights.permute(0, 2, 1))
        hidden_states = self.proj_out(hidden_states)
        return residual + hidden_states


class WavTokenizerVocosBackbone(nn.Module):
    """Vocos-style decoder backbone: embedding conv, positional conv/attention net, and ConvNeXt blocks."""

    def __init__(self, config: WavTokenizerConfig):
        super().__init__()
        self.embed = nn.Conv1d(config.hidden_size, config.decoder_hidden_size, kernel_size=7, padding=3)
        self.pos_net = nn.ModuleList(
            [
                WavTokenizerVocosResnetBlock(config),
                WavTokenizerVocosResnetBlock(config),
                WavTokenizerVocosAttention(config),
                WavTokenizerVocosResnetBlock(config),
                WavTokenizerVocosResnetBlock(config),
                nn.GroupNorm(config.decoder_attention_num_groups, config.decoder_hidden_size, eps=config.norm_eps),
            ]
        )
        self.norm = WavTokenizerAdaLayerNorm(config)
        self.convnext = nn.ModuleList([WavTokenizerConvNeXtBlock(config) for _ in range(config.decoder_num_layers)])
        self.final_layer_norm = nn.LayerNorm(config.decoder_hidden_size, eps=config.norm_eps)

    def forward(self, hidden_states: torch.Tensor, bandwidth_id: torch.Tensor) -> torch.Tensor:
        hidden_states = self.embed(hidden_states)
        for layer in self.pos_net:
            hidden_states = layer(hidden_states)
        hidden_states = self.norm(hidden_states.transpose(1, 2), bandwidth_id)
        hidden_states = hidden_states.transpose(1, 2)
        for layer in self.convnext:
            hidden_states = layer(hidden_states, bandwidth_id)
        return self.final_layer_norm(hidden_states.transpose(1, 2))


class WavTokenizerISTFTHead(nn.Module):
    """
    Head for converting decoder outputs to waveform via STFT projection and ISTFT.

    Uses custom "same" padding ISTFT from Vocos:
    https://github.com/gemelo-ai/vocos/blob/c859e3b7b534f3776a357983029d34170ddd6fc3/vocos/spectral_ops.py#L47
    """

    def __init__(self, config: WavTokenizerConfig):
        super().__init__()
        # WavTokenizer's decoder backbone dimension differs from the encoder latent dimension
        self.linear = nn.Linear(config.decoder_hidden_size, config.n_fft + 2)
        self.n_fft = config.n_fft
        self.hop_length = config.hop_length
        self.padding = (self.n_fft - self.hop_length) // 2
        window = torch.hann_window(config.n_fft)
        self.register_buffer("window", window, persistent=False)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        stft_pred = self.linear(hidden_states).transpose(1, 2)
        magnitude, phase = stft_pred.chunk(2, dim=1)
        # Cast to float32: complex exponential and irfft are not supported for fp16 (ComplexHalf)
        magnitude = magnitude.float()
        phase = phase.float()
        # Clamp like original: https://huggingface.co/HKUSTAudio/wavtokenizer/blob/main/vq/codec_decoder_vocos.py#L138
        magnitude = torch.exp(magnitude).clamp(max=1e2)
        spectrogram_complex = magnitude * torch.exp(1j * phase)

        # Back to audio (ISTFT with manual "same" padding: torch.istft lacks a native same-padding mode,
        # so we use irfft + fold with explicit pre-computed padding to replicate it)
        time_frames = torch.fft.irfft(spectrogram_complex, self.n_fft, dim=1, norm="backward")
        time_frames = time_frames * self.window[None, :, None]
        num_frames = spectrogram_complex.shape[-1]
        output_size = (num_frames - 1) * self.hop_length + self.n_fft
        audio = F.fold(
            time_frames,
            output_size=(1, output_size),
            kernel_size=(1, self.n_fft),
            stride=(1, self.hop_length),
        )[:, 0, 0, self.padding : -self.padding]

        # Normalize
        window_envelope = F.fold(
            self.window.square().expand(1, num_frames, -1).transpose(1, 2),
            output_size=(1, output_size),
            kernel_size=(1, self.n_fft),
            stride=(1, self.hop_length),
        ).squeeze()[self.padding : -self.padding]
        # Clamp as expected by original: https://huggingface.co/HKUSTAudio/wavtokenizer/blob/main/vq/codec_decoder_vocos.py#L82
        window_envelope = window_envelope.clamp(min=1e-11)
        audio = audio / window_envelope
        return audio.unsqueeze(1)


@auto_docstring
class WavTokenizerPreTrainedModel(PreTrainedAudioTokenizerBase):
    config: WavTokenizerConfig
    base_model_prefix = "wavtokenizer"
    main_input_name = "input_values"
    input_modalities = ("audio",)

    @torch.no_grad()
    def _init_weights(self, module):
        super()._init_weights(module)
        if isinstance(module, nn.Conv1d):
            init.kaiming_normal_(module.weight)
            if module.bias is not None:
                k = math.sqrt(module.groups / (module.in_channels * module.kernel_size[0]))
                init.uniform_(module.bias, a=-k, b=k)
        elif isinstance(module, WavTokenizerConv1d):
            kernel_size = module.conv.kernel_size[0]
            stride = torch.tensor(module.conv.stride[0], dtype=torch.int64)
            dilation = module.conv.dilation[0]
            # Effective kernel size with dilations.
            kernel_size = torch.tensor((kernel_size - 1) * dilation + 1, dtype=torch.int64)
            init.copy_(module.stride, stride)
            init.copy_(module.kernel_size, kernel_size)
            init.copy_(module.padding_total, kernel_size - stride)
        elif isinstance(module, WavTokenizerEuclideanCodebook):
            init.copy_(module.inited, torch.Tensor([True]))
            init.zeros_(module.cluster_size)
            init.zeros_(module.embed)
            init.zeros_(module.embed_avg)
        if isinstance(module, WavTokenizerAdaLayerNorm):
            init.ones_(module.scale.weight)
            init.zeros_(module.shift.weight)
        elif isinstance(module, WavTokenizerConvNeXtBlock):
            init.constant_(module.gamma, 1.0 / self.config.decoder_num_layers)
        elif isinstance(module, WavTokenizerISTFTHead):
            window = torch.hann_window(module.n_fft)
            init.copy_(module.window, window)


@auto_docstring(
    custom_intro="""
    The WavTokenizer neural acoustic codec model: a single-codebook discrete audio tokenizer.

    Proposed in [WavTokenizer: an Efficient Acoustic Discrete Codec Tokenizer for Audio Language Modeling](https://huggingface.co/papers/2408.16532)
    by Ji et al. (ICLR 2025). Ported from the original (MIT-licensed) implementation at
    https://github.com/jishengpeng/WavTokenizer.
    """
)
class WavTokenizerModel(WavTokenizerPreTrainedModel):
    def __init__(self, config: WavTokenizerConfig):
        super().__init__(config)
        self.config = config
        self.hop_length = config.hop_length

        self.encoder = WavTokenizerEncoder(config)
        self.quantizer = WavTokenizerVectorQuantization(config)
        self.backbone = WavTokenizerVocosBackbone(config)
        self.head = WavTokenizerISTFTHead(config)

        # Initialize weights and apply final processing
        self.post_init()

    @auto_docstring
    @can_return_tuple
    def encode(
        self,
        input_values: torch.Tensor,
        padding_mask: torch.Tensor | None = None,
        **kwargs,
    ) -> tuple | WavTokenizerEncoderOutput:
        r"""
        input_values (`torch.Tensor` of shape `(batch_size, 1, sequence_length)`):
            Input audio waveform. Arbitrary non-zero lengths are supported; the encoder pads internally and emits
            `ceil(sequence_length / hop_length)` codes. Note that decoding requires at least 2 codes (see
            [`~WavTokenizerModel.decode`]).

            <Tip warning={true}>

            Run the model in `float32` for reproducible codes: code assignment is a nearest-neighbour argmin over
            codebook distances, and half precision (`bfloat16`/`float16`) perturbs the embeddings enough to flip a
            large fraction of codes near decision boundaries.

            </Tip>
        padding_mask (`torch.Tensor` of shape `(batch_size, sequence_length)` or `(batch_size, 1, sequence_length)`, *optional*):
            Padding mask used to pad `input_values`; used to compute `audio_codes_mask`.
        """
